// Package filepath implements gomplate's `filepath` template-function
// namespace. The functions are thin wrappers over Go's standard
// `path/filepath` package, with non-string arguments coerced to strings
// (nil becomes "nil", everything else via fmt's %v semantics), matching
// the reference behaviour.
package filepath

import (
	"fmt"
	stdfilepath "path/filepath"
)

// NS returns the namespace object whose methods are the `filepath` template
// functions.
func NS() any {
	return &ns{}
}

type ns struct{}

func toString(in any) string {
	if in == nil {
		return "nil"
	}
	if s, ok := in.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", in)
}

// Base implements filepath.Base.
func (n *ns) Base(in any) string {
	return stdfilepath.Base(toString(in))
}

// Clean implements filepath.Clean.
func (n *ns) Clean(in any) string {
	return stdfilepath.Clean(toString(in))
}

// Dir implements filepath.Dir.
func (n *ns) Dir(in any) string {
	return stdfilepath.Dir(toString(in))
}

// Ext implements filepath.Ext.
func (n *ns) Ext(in any) string {
	return stdfilepath.Ext(toString(in))
}

// FromSlash implements filepath.FromSlash.
func (n *ns) FromSlash(in any) string {
	return stdfilepath.FromSlash(toString(in))
}

// IsAbs implements filepath.IsAbs.
func (n *ns) IsAbs(in any) bool {
	return stdfilepath.IsAbs(toString(in))
}

// Join implements filepath.Join.
func (n *ns) Join(elem ...any) string {
	s := make([]string, len(elem))
	for i, e := range elem {
		s[i] = toString(e)
	}
	return stdfilepath.Join(s...)
}

// Match implements filepath.Match.
func (n *ns) Match(pattern, name any) (bool, error) {
	return stdfilepath.Match(toString(pattern), toString(name))
}

// Rel implements filepath.Rel.
func (n *ns) Rel(basepath, targpath any) (string, error) {
	return stdfilepath.Rel(toString(basepath), toString(targpath))
}

// Split implements filepath.Split. It returns a two-element slice holding
// the directory and file name components.
func (n *ns) Split(in any) []string {
	dir, file := stdfilepath.Split(toString(in))
	return []string{dir, file}
}

// ToSlash implements filepath.ToSlash.
func (n *ns) ToSlash(in any) string {
	return stdfilepath.ToSlash(toString(in))
}

// VolumeName implements filepath.VolumeName.
func (n *ns) VolumeName(in any) string {
	return stdfilepath.VolumeName(toString(in))
}

package filepath

import (
	"bytes"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"filepath": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

func TestFilepath(t *testing.T) {
	tests := []struct {
		name string
		tmpl string
		want string
	}{
		// Base
		{"base doc example", `{{ filepath.Base "/tmp/foo" }}`, "foo"},
		{"base empty", `{{ filepath.Base "" }}`, "."},
		{"base root", `{{ filepath.Base "/" }}`, "/"},
		{"base trailing sep", `{{ filepath.Base "/tmp/foo/" }}`, "foo"},
		{"base all separators", `{{ filepath.Base "////" }}`, "/"},
		{"base no separators", `{{ filepath.Base "foo" }}`, "foo"},
		{"base int coercion", `{{ filepath.Base 42 }}`, "42"},
		{"base float coercion", `{{ filepath.Base 4.2 }}`, "4.2"},
		{"base bool coercion", `{{ filepath.Base true }}`, "true"},
		{"base nil coercion", `{{ filepath.Base nil }}`, "nil"},
		{"base pipeline", `{{ "/tmp/foo" | filepath.Base }}`, "foo"},

		// Clean
		{"clean doc example", `{{ filepath.Clean "/tmp//foo/../" }}`, "/tmp"},
		{"clean empty", `{{ filepath.Clean "" }}`, "."},
		{"clean dot", `{{ filepath.Clean "." }}`, "."},
		{"clean already clean", `{{ filepath.Clean "/tmp/foo" }}`, "/tmp/foo"},
		{"clean float coercion", `{{ filepath.Clean 1.5 }}`, "1.5"},
		{"clean pipeline", `{{ "/tmp//foo/../" | filepath.Clean }}`, "/tmp"},

		// Dir
		{"dir doc example", `{{ filepath.Dir "/tmp/foo" }}`, "/tmp"},
		{"dir empty", `{{ filepath.Dir "" }}`, "."},
		{"dir root", `{{ filepath.Dir "/" }}`, "/"},
		{"dir no separators", `{{ filepath.Dir "foo" }}`, "."},
		{"dir nil coercion", `{{ filepath.Dir nil }}`, "."},
		{"dir pipeline", `{{ "/tmp/foo" | filepath.Dir }}`, "/tmp"},

		// Ext
		{"ext doc example", `{{ filepath.Ext "/tmp/foo.csv" }}`, ".csv"},
		{"ext no extension", `{{ filepath.Ext "/tmp/foo" }}`, ""},
		{"ext empty", `{{ filepath.Ext "" }}`, ""},
		{"ext dotfile", `{{ filepath.Ext ".hidden" }}`, ".hidden"},
		{"ext dot in dir only", `{{ filepath.Ext "/a.b/c" }}`, ""},
		{"ext float coercion", `{{ filepath.Ext 3.14 }}`, ".14"},
		{"ext pipeline", `{{ "/tmp/foo.csv" | filepath.Ext }}`, ".csv"},

		// FromSlash
		{"fromslash doc example", `{{ filepath.FromSlash "/foo/bar" }}`, "/foo/bar"},
		{"fromslash empty", `{{ filepath.FromSlash "" }}`, ""},
		{"fromslash float coercion", `{{ filepath.FromSlash 1.5 }}`, "1.5"},
		{"fromslash pipeline", `{{ "/foo/bar" | filepath.FromSlash }}`, "/foo/bar"},

		// IsAbs
		{"isabs doc example abs", `{{ if (filepath.IsAbs "/tmp/foo.csv") }}absolute{{else}}relative{{end}}`, "absolute"},
		{"isabs doc example rel", `{{ if (filepath.IsAbs "../foo.csv") }}absolute{{else}}relative{{end}}`, "relative"},
		{"isabs empty", `{{ filepath.IsAbs "" }}`, "false"},
		{"isabs int coercion", `{{ filepath.IsAbs 42 }}`, "false"},
		{"isabs pipeline", `{{ "/tmp/foo.csv" | filepath.IsAbs }}`, "true"},

		// Join
		{"join doc example", `{{ filepath.Join "/tmp" "foo" "bar" }}`, "/tmp/foo/bar"},
		{"join zero args", `{{ filepath.Join }}`, ""},
		{"join one arg", `{{ filepath.Join "/tmp" }}`, "/tmp"},
		{"join empty element", `{{ filepath.Join "a" "" "b" }}`, "a/b"},
		{"join cleans result", `{{ filepath.Join "a" "../b" }}`, "b"},
		{"join int coercion", `{{ filepath.Join "a" 1 "b" }}`, "a/1/b"},
		{"join ints only", `{{ filepath.Join 1 2 }}`, "1/2"},
		{"join nil coercion", `{{ filepath.Join "a" nil }}`, "a/nil"},
		{"join nil only", `{{ filepath.Join nil }}`, "nil"},
		{"join pipeline", `{{ "b" | filepath.Join "a" }}`, "a/b"},

		// Match
		{"match doc example", `{{ filepath.Match "*.csv" "foo.csv" }}`, "true"},
		{"match no match", `{{ filepath.Match "*.csv" "foo.txt" }}`, "false"},
		{"match separator not matched", `{{ filepath.Match "*.csv" "/foo.csv" }}`, "false"},
		{"match question mark", `{{ filepath.Match "fo?" "foo" }}`, "true"},
		{"match char class", `{{ filepath.Match "[a-z]oo" "foo" }}`, "true"},
		{"match int coercion", `{{ filepath.Match "*" 42 }}`, "true"},
		{"match int pattern", `{{ filepath.Match 42 "42" }}`, "true"},
		{"match pipeline", `{{ "foo.csv" | filepath.Match "*.csv" }}`, "true"},

		// Rel
		{"rel doc example", `{{ filepath.Rel "/a" "/a/b/c" }}`, "b/c"},
		{"rel dotdot", `{{ filepath.Rel "a/b" "a/c" }}`, "../c"},
		{"rel empty paths", `{{ filepath.Rel "" "" }}`, "."},
		{"rel dot base", `{{ filepath.Rel "." "x" }}`, "x"},
		{"rel same path", `{{ filepath.Rel "/a/b" "/a/b" }}`, "."},
		{"rel pipeline", `{{ "/a/b/c" | filepath.Rel "/a" }}`, "b/c"},

		// Split
		{"split doc example", `{{ $p := filepath.Split "/tmp/foo" }}{{ $dir := index $p 0 }}{{ $file := index $p 1 }}dir is {{$dir}}, file is {{$file}}`, "dir is /tmp/, file is foo"},
		{"split printed", `{{ filepath.Split "/tmp/foo" }}`, "[/tmp/ foo]"},
		{"split empty", `{{ filepath.Split "" }}`, "[ ]"},
		{"split root", `{{ filepath.Split "/" }}`, "[/ ]"},
		{"split no separator", `{{ filepath.Split "foo" }}`, "[ foo]"},
		{"split int coercion", `{{ filepath.Split 42 }}`, "[ 42]"},
		{"split index", `{{ index (filepath.Split "/a/b") 0 }}|{{ index (filepath.Split "/a/b") 1 }}`, "/a/|b"},
		{"split pipeline", `{{ "/tmp/foo" | filepath.Split }}`, "[/tmp/ foo]"},

		// ToSlash
		{"toslash doc example", `{{ filepath.ToSlash "/foo/bar" }}`, "/foo/bar"},
		{"toslash empty", `{{ filepath.ToSlash "" }}`, ""},
		{"toslash bool coercion", `{{ filepath.ToSlash true }}`, "true"},
		{"toslash pipeline", `{{ "/foo/bar" | filepath.ToSlash }}`, "/foo/bar"},

		// VolumeName
		{"volumename doc example", `volume is {{ filepath.VolumeName "/foo/bar" }}`, "volume is "},
		{"volumename windows path on linux", `{{ filepath.VolumeName "C:/foo/bar" }}`, ""},
		{"volumename empty", `{{ filepath.VolumeName "" }}`, ""},
		{"volumename int coercion", `{{ filepath.VolumeName 0 }}`, ""},
		{"volumename pipeline", `{{ "/foo/bar" | filepath.VolumeName }}`, ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := render(t, tt.tmpl)
			if err != nil {
				t.Fatalf("render %q: unexpected error: %v", tt.tmpl, err)
			}
			if got != tt.want {
				t.Errorf("render %q = %q, want %q", tt.tmpl, got, tt.want)
			}
		})
	}
}

func TestFilepathErrors(t *testing.T) {
	tests := []struct {
		name    string
		tmpl    string
		wantErr string
	}{
		{
			"match bad pattern",
			`{{ filepath.Match "[[" "foo" }}`,
			"error calling Match: syntax error in pattern",
		},
		{
			"match bad char class pattern",
			`{{ filepath.Match "[a-" "foo" }}`,
			"error calling Match: syntax error in pattern",
		},
		{
			"rel rel base abs target",
			`{{ filepath.Rel "a" "/b" }}`,
			"error calling Rel: Rel: can't make /b relative to a",
		},
		{
			"rel abs base rel target",
			`{{ filepath.Rel "/a" "b" }}`,
			"error calling Rel: Rel: can't make b relative to /a",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := render(t, tt.tmpl)
			if err == nil {
				t.Fatalf("render %q: expected error, got none", tt.tmpl)
			}
			if !strings.Contains(err.Error(), tt.wantErr) {
				t.Errorf("render %q error = %q, want it to contain %q", tt.tmpl, err.Error(), tt.wantErr)
			}
		})
	}
}
